'use strict';
/* Lab visuals refresh: topic-specific experiment scenes and apparatus cards. */
/* ---------- Физика по учебнику: уроки с роликами, карточки, симуляции, проверки, опыт, уровни, комбо ---------- */
const $ = (s, r = document) => r.querySelector(s);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const nl = s => esc(s).replace(/\n/g, '<br>');
// вектор: буква + U+20D7 → буква со стрелкой (шрифты телефонов часто не ставят стрелку над буквой)
const vx = s => esc(s).replace(/(.)\u20D7/gu, '<span class="vec">$1</span>');
const nlv = s => vx(s).replace(/\n/g, '<br>');
const f1 = (v, d = 1) => (Math.round(v * 10 ** d) / 10 ** d).toString().replace('.', ',');
const plural = (n, a, b, c) => n + ' ' + (n % 10 === 1 && n % 100 !== 11 ? a : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? b : c);
const shuffle = a => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.random() * (i + 1) | 0; [a[i], a[j]] = [a[j], a[i]]; } return a; };
const mmss = s => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
const buzz = ms => { try { navigator.vibrate && navigator.vibrate(ms); } catch (e) {} };
const dayKey = (d = new Date()) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');

/* ---------- профиль игрока ---------- */
const S0 = { name: '', ava: 0, xp: 0, days: [], combo: 0, bestCombo: 0, ok: 0, tot: 0, lessons: {}, steps: {}, boss: {}, badges: [], sci: [], xpDay: { d: '', xp: 0 }, wrong: [], stat: {}, fav: [], hist: [] };
let S = (() => { try { return Object.assign({}, S0, JSON.parse(localStorage.getItem('f2') || '{}')); } catch (e) { return Object.assign({}, S0); } })();
const save = () => { try { localStorage.setItem('f2', JSON.stringify(S)); } catch (e) {} };

/* ---------- уровни ---------- */
const TITLES = [[1, 'Наблюдатель'], [5, 'Экспериментатор'], [10, 'Исследователь'], [15, 'Инженер'], [20, 'Теоретик'], [25, 'Академик']];
const needFor = l => 100 + 40 * (l - 1); // опыта от уровня l до l+1
function levelOf(xp) { let l = 1, left = xp; while (left >= needFor(l)) { left -= needFor(l); l++; } return { l, cur: left, need: needFor(l), title: TITLES.filter(t => l >= t[0]).pop()[1] }; }
const DAY_GOAL = 50;
function markDay() { const k = dayKey(); if (S.days[S.days.length - 1] !== k) { S.days.push(k); S.days = S.days.slice(-200); } }
function streak() { const d = new Set(S.days), x = new Date(); let n = 0; if (!d.has(dayKey(x))) x.setDate(x.getDate() - 1); while (d.has(dayKey(x))) { n++; x.setDate(x.getDate() - 1); } return n; }
const xpToday = () => S.xpDay.d === dayKey() ? S.xpDay.xp : 0;
function addXP(n, why) {
  if (n <= 0) return;
  const before = levelOf(S.xp).l, goalBefore = xpToday() >= DAY_GOAL;
  S.xp += n; S.xpDay = { d: dayKey(), xp: xpToday() + n }; markDay();
  if (!goalBefore && xpToday() >= DAY_GOAL) { S.xp += 30; S.xpDay.xp += 30; setTimeout(() => toast(ic('target') + 'Цель дня выполнена · +30 XP', 'gold'), 900); }
  save(); floatXP(n, why); hdrUpd();
  const after = levelOf(S.xp).l; if (after > before) setTimeout(() => levelUp(after), 600);
  checkBadges();
}

/* ---------- комбо: подряд верные ответы умножают опыт ---------- */
const mult = c => c >= 10 ? 4 : c >= 6 ? 3 : c >= 3 ? 2 : 1;
function comboAnswer(ok) {
  S.tot++; if (ok) { S.ok++; S.combo++; if (S.combo > S.bestCombo) S.bestCombo = S.combo; } else S.combo = 0;
  const m = mult(S.combo), gained = ok ? 5 * m : 0; save();
  if (ok && [3, 6, 10].includes(S.combo)) toast(ic('flame') + `Комбо ×${m}! ${S.combo} подряд`, 'fire');
  return gained;
}
const comboChip = () => `<span class="combo${S.combo >= 3 ? ' hot' : ''}" id="combo">${ic('flame')}<b>${S.combo}</b>${S.combo >= 3 ? `<i>×${mult(S.combo)}</i>` : ''}</span>`;

/* ---------- значки ---------- */
const BADGES = [
  ['first', 'Первый шаг', 'Пройди первый урок', s => Object.keys(s.lessons).length >= 1],
  ['ch1', 'Кинематик', 'Пройди финальное испытание главы 1', s => s.boss[1] >= 80],
  ['c5', 'Разогрев', 'Комбо из 5 ответов', s => s.bestCombo >= 5],
  ['c10', 'В ударе', 'Комбо из 10 ответов', s => s.bestCombo >= 10],
  ['c20', 'Неудержимый', 'Комбо из 20 ответов', s => s.bestCombo >= 20],
  ['st3', 'Три дня подряд', 'Занимайся 3 дня подряд', () => streak() >= 3],
  ['st7', 'Неделя физики', 'Занимайся 7 дней подряд', () => streak() >= 7],
  ['lv5', 'Экспериментатор', 'Достигни 5 уровня', s => levelOf(s.xp).l >= 5],
  ['q100', 'Сотня', 'Ответь на 100 вопросов', s => s.tot >= 100],
  ['perfect', 'Без единой ошибки', 'Пройди проверку урока на 100%', s => Object.values(s.lessons).some(l => l.best === 100)],
  ['q50', 'Практик', 'Ответь на 50 вопросов', s => s.tot >= 50],
  ['xp500', 'Энергия знаний', 'Набери 500 XP', s => s.xp >= 500],
  ['l10', 'Путь исследователя', 'Пройди 10 уроков', s => Object.keys(s.lessons).length >= 10],
  ['perfect5', 'Точность', 'Пять раз пройди урок без ошибок', s => Object.values(s.lessons).filter(l => l.best === 100).length >= 5]
];
function checkBadges() {
  BADGES.forEach(([id, t, , f]) => { if (!S.badges.includes(id) && f(S)) { S.badges.push(id); save(); setTimeout(() => toast(ic('award') + 'Новый значок: ' + t, 'gold'), 1200); } });
}

/* ---------- всплывашки ---------- */
function toast(html, kind = '') { const t = document.createElement('div'); t.className = 'toast ' + kind; t.innerHTML = html; $('#toasts').appendChild(t); setTimeout(() => t.classList.add('out'), 2300); setTimeout(() => t.remove(), 2800); }
function floatXP(n) { const f = document.createElement('div'); f.className = 'fxp'; f.textContent = '+' + n + ' XP'; document.body.appendChild(f); setTimeout(() => f.remove(), 1200); }
function levelUp(l) { const L = levelOf(S.xp); sheet(`<div class="lvup"><div class="lvnum">${l}</div><b>Новый уровень!</b><p>Ты теперь — <b>${L.title}</b>. До следующего уровня ${L.need} XP.</p><button class="btn wide" data-act="closeSheet">Дальше</button></div>`); buzz([20, 60, 20]); }
function sheet(html) { const s = $('#sheet'); s.innerHTML = `<div class="sbox">${html}</div>`; s.hidden = false; }
const closeSheet = () => { const s = $('#sheet'); s.hidden = true; s.innerHTML = ''; };

/* ---------- маршруты ---------- */
// '' главная · book учебник · c1 глава · l1-2 урок · boss1 финал главы · train тренировка · quiz идёт проверка · profile профиль
function route() {
  const h = location.hash.replace(/^#/, ''); let m;
  if ((m = /^c(\d+)$/.exec(h))) return { name: 'chapter', ch: +m[1], tab: 'book', parent: 'book' };
  if ((m = /^l(\d+)-(\d+)$/.exec(h))) return { name: 'lesson', ch: +m[1], li: +m[2], tab: 'book', parent: 'c' + m[1] };
  if (h === 'quiz') return { name: 'quiz', tab: '', parent: '' };
  if (h === 'lab') return { name: 'labWorks', tab: 'lab' };
  if (h === 'lab-exps') return { name: 'lab', tab: 'lab', parent: 'lab' };
  if (h === 'lw-1') return { name: 'labWork', tab: 'lab', parent: 'lab' };
  if (h === 'lw-1-report') return { name: 'labWorkReport', tab: 'lab', parent: 'lw-1' };
  if (h === 'sandbox') return { name: 'sandbox', tab: 'lab', parent: 'lab-exps' };
  if (h === 'reader') return { name: 'reader', tab: 'book', parent: 'home' };
  if ((m = /^read-(\d+)$/.exec(h))) return { name: 'readerChapter', ch: +m[1], tab: 'book', parent: 'reader' };
  if (h === 'lab-games') return { name: 'labGames', tab: 'lab', parent: 'lab' };
  if (h === 'game-bridge') return { name: 'bridgeGame', tab: 'lab', parent: 'lab-games' };
  if ((m = /^lab-ch-(\d+)$/.exec(h))) return { name: 'labChapter', ch: +m[1], tab: 'lab', parent: 'lab-exps' };
  if ((m = /^lab-topic-(\d+)-(\d+)$/.exec(h))) return { name: 'labTopic', ch: +m[1], topic: +m[2], tab: 'lab', parent: 'lab-ch-' + m[1] };
  if ((m = /^lab-exp-([a-z0-9-]+)$/.exec(h))) return { name: 'labExp', exp: m[1], tab: 'lab', parent: 'lab-ch-' + ((LABS[m[1]]||{}).ch||1) };
  if ((m = /^lab-(spring|pendulum|fall|projectile|incline|wave|ohm|refraction|buoyancy|gas)$/.exec(h))) return { name: 'labExp', exp: LAB_LEGACY_MAP[m[1]] ? LAB_LEGACY_MAP[m[1]] : m[1], tab: 'lab', parent: 'lab' };
  if (h === 'hist' || h === 'qsearch') return { name: h, tab: 'train', parent: 'train' };
  if (['book', 'train', 'profile'].includes(h)) return { name: h, tab: h };
  return { name: 'home', tab: 'home' };
}
let SB = null; // initialized before the first route render; sandbox module assigns its state here.
const ui = {};
let lastHash = null, same = false;
function render() {
  stopLoops();
  if (typeof LAB !== 'undefined' && LAB.run && !location.hash.startsWith('#lab-exp-')) labStop('Пауза');
  const r = route(), y = ui.main.scrollTop; same = lastHash === location.hash; lastHash = location.hash;
  document.body.dataset.view = r.name;
  ui.tabs.querySelectorAll('a').forEach(a => a.classList.toggle('on', a.dataset.tab === r.tab));
  ui.tabs.hidden = r.name === 'quiz' || r.name === 'lesson';
  ({ home: vHome, book: vBook, chapter: vChapter, lesson: vLesson, quiz: vQuiz, train: vTrain, lab: vLab, labGames: vLabGames, labWorks: vLabWorks, labWork: vLabWork, labWorkReport: vLabWorkReport, labChapter: vLabChapter, labTopic: vLabTopic, labExp: vLabExp, profile: vProfile, bridgeGame: vBridgeGame, sandbox: vSandbox, reader: vReader, readerChapter: vReaderChapter, hist: vHist, qsearch: vQSearch })[r.name](r);
  if (same) ui.main.scrollTop = y; else ui.main.scrollTop = 0;
}
function frame(title, { back = false, sub = '' } = {}) {
  ui.ttl.innerHTML = title + (sub ? `<small>${sub}</small>` : ''); ui.back.hidden = !back; hdrUpd();
}
function hdrUpd() { const L = levelOf(S.xp); ui.lv.innerHTML = `<span class="lvb">${L.l}</span><span class="lvbar"><i style="width:${L.cur / L.need * 100}%"></i></span>`; }
function setMain(html) { ui.main.innerHTML = html; ui.main.classList.remove('enter'); if (!same) { void ui.main.offsetWidth; ui.main.classList.add('enter'); } }

/* ---------- данные уроков ---------- */
const chReady = n => !!CONTENT[n];
const lessonKey = (ch, li) => ch + '-' + li;
const lessonDone = (ch, li) => !!S.lessons[lessonKey(ch, li)];
function nextLesson() {
  for (const ch of CHAPTERS) { const C1 = CONTENT[ch.n]; if (!C1) continue; const i = C1.lessons.findIndex((_, k) => !lessonDone(ch.n, k + 1)); if (i >= 0) return { ch, C1, li: i + 1, L: C1.lessons[i] }; if (!(S.boss[ch.n] >= 80)) return { ch, C1, boss: true }; }
  return null;
}
const chapterProgress = n => { const C1 = CONTENT[n]; if (!C1) return 0; const d = C1.lessons.filter((_, k) => lessonDone(n, k + 1)).length + (S.boss[n] >= 80 ? 1 : 0); return d / (C1.lessons.length + 1); };

/* ---------- Главная ---------- */
function vHome() {
  frame('Физика');
  if (!BANK) { bank().then(() => { if (route().name === 'home') render(); }); }
  const L = levelOf(S.xp), st = streak(), nx = nextLesson(), today = xpToday(), gp = Math.min(1, today / DAY_GOAL);
  const hi = S.name ? `Привет, ${esc(S.name)}!` : 'Привет!';
  // экзамен — главное: готовность, ошибки, повторение
  const B = BANK || [], seen = B.filter(x => isSeen(x.key)).length, errs = B.filter(x => isErr(x.key)).length, due = B.filter(x => isDue(x.key)).length, rd = readiness();
  const ready = `<section class="card exready"><div class="ext">${ringBig(rd ? rd.pct : (B.length ? Math.round(seen / B.length * 100) : 0))}<div><small class="mute">${rd ? 'Готовность к экзамену' : 'Подготовка к экзамену'}</small><b class="h">${rd ? `Прогноз — «${rd.mark}»` : 'Пройди пробный экзамен'}</b><small class="mute">${rd ? `средний балл ${rd.pct} · «3» — 60, «4» — 75, «5» — 90` : '30 вопросов — и я покажу прогноз оценки'}</small></div></div>` +
    `<button class="cta" data-act="examSetup">${ic('graduation-cap', 'big')}<span><b>Пробный экзамен</b><small>30 вопросов · оценка по шкале 60/75/90</small></span>${ic('chevron-right')}</button>` +
    `<div class="exstats"><a href="#train"><b>${seen}</b><small>из ${B.length || 900} решено</small></a><button data-act="errs"><b class="${errs ? 'pink' : ''}">${errs}</b><small>ошибок</small></button><button data-act="due"><b class="${due ? 'gold' : ''}">${due}</b><small>повторить</small></button></div></section>`;
  let cont = '';
  if (nx && !nx.boss) cont = `<a class="cont" href="#l${nx.ch.n}-${nx.li}"><span class="cart">${chapterArt(nx.ch)}</span><span class="ctx"><small>Курс · глава ${nx.ch.n} · ${esc(nx.L.par)}</small><b>${esc(nx.L.title)}</b><span class="cbtn">${ic('play')}Продолжить урок</span></span></a>`;
  else if (nx) cont = `<button class="cont" data-act="boss" data-ch="${nx.ch.n}"><span class="cart">${chapterArt(nx.ch)}</span><span class="ctx"><small>Курс · глава ${nx.ch.n}</small><b>Финальное испытание</b><span class="cbtn">${ic('swords')}В бой</span></span></button>`;
  const name = S.name ? esc(S.name) : '';
  const cta2 = nx && !nx.boss ? `<a class="btn line" href="#l${nx.ch.n}-${nx.li}">${ic('play')}Продолжить</a>` : `<a class="btn line" href="#book">${ic('book-open')}Открыть учебник</a>`;
  const hero = `<section class="hero"><div class="hero-txt"><small class="eyebrow">Курс физики · Т. И. Трофимова</small>` +
    `<h1>${name ? `${name}, продолжим подготовку` : 'Физика к экзамену — шаг за шагом'}</h1>` +
    `<p class="lead">33 главы учебника с видеоуроками, 900 экзаменационных вопросов с разбором, виртуальная лаборатория и лабораторные работы с отчётом.</p>` +
    `<div class="hero-cta"><button class="btn" data-act="examSetup">${ic('graduation-cap')}Пробный экзамен</button>${cta2}</div>` +
    `<a href="#profile" class="hero-lv">${avatarSvg(S.ava, 34)}<span><b>${esc(L.title)} · ур. ${L.l}</b><span class="bar"><i style="width:${L.cur / L.need * 100}%"></i></span></span><small>${S.xp} XP</small></a></div>${ready}</section>`;
  const sections = [['#book', 'layers', 'gold', 'Учебник', `${CHAPTERS.length} глав · уроки, карточки, видео`], ['#train', 'graduation-cap', 'blue', 'Тесты', '900 вопросов · экзамен и тренировка'],
    ['#lab', 'flask-conical', 'mint', 'Практикум', 'лабораторные работы и опыты'], ['#reader', 'book-open', 'violet', 'Конспекты', 'краткое изложение всех глав']];
  setMain(hero + (cont ? `<h2 class="sec">Продолжить</h2>` + cont : '') +
    `<h2 class="sec">Разделы</h2><div class="quick4 sections">${sections.map(([h, i, c, t, d]) => `<a href="${h}">${ic(i, c)}<span><b>${t}</b><small>${d}</small></span></a>`).join('')}<button data-act="quick">${ic('zap', 'coral')}<span><b>Быстрый тест</b><small>10 случайных вопросов</small></span></button></div>` +
    `<h2 class="sec">Сегодня</h2><section class="duo"><div class="card goal">${ring(gp)}<div><b>Цель дня</b><small>${today} / ${DAY_GOAL} XP</small></div></div><div class="card goal">${ic('flame', 'big fire')}<div><b>${st ? plural(st, 'день', 'дня', 'дней') : 'Нет серии'}</b><small>серия занятий</small></div></div></section>`);
}
function ring(f) { const r = 26, L = 2 * Math.PI * r; return `<svg class="ring" viewBox="0 0 64 64"><circle cx="32" cy="32" r="${r}" stroke="var(--line)" stroke-width="7" fill="none"/><circle cx="32" cy="32" r="${r}" stroke="var(--gold)" stroke-width="7" fill="none" stroke-linecap="round" stroke-dasharray="${L}" stroke-dashoffset="${L * (1 - f)}" transform="rotate(-90 32 32)"/></svg>`; }

/* ---------- Учебник ---------- */
function vBook() {
  frame('Учебник', { sub: 'по курсу физики Т. И. Трофимовой' });
  setMain(PARTS.map(P => {
    const chs = CHAPTERS.filter(c => c.part === P.n);
    return `<section class="part" style="--pc:${P.col}"><div class="ph"><span class="pn">Часть ${P.n}</span><h2>${esc(P.title)}</h2></div>` +
      chs.map(ch => {
        const ready = chReady(ch.n), pr = chapterProgress(ch.n), notes = !ready && !!READER_NOTES[ch.n];
        if (notes) return `<a href="#read-${ch.n}" class="chrow notes"><span class="cthumb">${chapterArt(ch)}</span><span class="cinfo"><small>Глава ${ch.n} · § ${ch.a}–${ch.b}</small><b>${esc(ch.title)}</b><span class="tag">конспект · уроки скоро</span></span>${ic('book-open')}</a>`;
        return `<${ready ? `a href="#c${ch.n}"` : 'div'} class="chrow${ready ? '' : ' soon'}"><span class="cthumb">${chapterArt(ch)}</span><span class="cinfo"><small>Глава ${ch.n} · § ${ch.a}–${ch.b}</small><b>${esc(ch.title)}</b>${ready ? `<span class="pbar"><i style="width:${pr * 100}%"></i></span>` : '<span class="tag">скоро</span>'}</span>${ready ? ic('chevron-right') : ic('lock', 'mute')}</${ready ? 'a' : 'div'}>`;
      }).join('') + '</section>';
  }).join(''));
}


/* ---------- Читатель конспектов по учебнику ---------- */
const READER_NOTES = {
  1: {
    lead: 'Как описать движение тела: модели, система отсчёта, путь и перемещение, скорость, ускорение и вращение.',
    sections: [
      {h:'Модели механики',p:'Механика изучает механическое движение — изменение взаимного расположения тел со временем. Кинематика описывает движение, не рассматривая его причин. Если размеры тела в задаче не важны, его заменяют материальной точкой; если тело не деформируется — абсолютно твёрдым телом. Любое движение твёрдого тела — сочетание поступательного и вращательного.',note:'Одно и то же тело может быть материальной точкой в одной задаче и не быть ею в другой: Земля на орбите — точка, а при расчёте суточного вращения — нет.'},
      {h:'Система отсчёта',p:'Положение точки задают относительно тела отсчёта. Тело отсчёта, связанная с ним система координат и часы образуют систему отсчёта. Положение точки описывают координаты или радиус-вектор, проведённый из начала координат; закон движения — это их зависимость от времени.',formula:'x = x(t),  y = y(t),  z = z(t)\nr⃗ = r⃗(t)'},
      {h:'Траектория, путь и перемещение',p:'Траектория — линия, которую описывает движущаяся точка. Путь — длина участка траектории, скалярная величина. Перемещение — вектор из начального положения в конечное. Путь не меньше модуля перемещения; они равны только при прямолинейном движении в одну сторону.',formula:'Δr⃗ = r⃗₂ − r⃗₁,   Δs ≥ |Δr⃗|',note:'После круга по стадиону путь — 400 м, а перемещение — ноль.'},
      {h:'Скорость',p:'Средняя скорость — отношение перемещения ко времени. При уменьшении промежутка времени секущая становится касательной, и получается мгновенная скорость — производная радиус-вектора по времени. Она направлена по касательной к траектории, её модуль — производная пути по времени. Путь равен площади под графиком модуля скорости.',formula:'⟨v⃗⟩ = Δr⃗/Δt,   v⃗ = dr⃗/dt,   v = ds/dt'},
      {h:'Ускорение и его составляющие',p:'Ускорение — производная скорости по времени. На криволинейной траектории его раскладывают на тангенциальное (по касательной, меняет модуль скорости) и нормальное (к центру кривизны, меняет направление). Составляющие перпендикулярны, полное ускорение находят по теореме Пифагора.',formula:'aτ = dv/dt,   aₙ = v²/r,   a = √(aτ² + aₙ²)',note:'При равномерном движении по окружности ускорение не равно нулю: есть нормальное ускорение v²/r.'},
      {h:'Равнопеременное движение',p:'Если тело движется по прямой с постоянным ускорением, скорость меняется линейно, а координата — по квадратичному закону. При торможении ускорение берут со знаком минус.',formula:'v = v₀ + at,   s = v₀t + at²/2'},
      {h:'Вращение: угловые величины',p:'При вращении удобно описывать поворот: угол поворота в радианах, угловую скорость — производную угла по времени — и угловое ускорение. У всех точек тела одна угловая скорость, а линейная скорость растёт с расстоянием до оси.',formula:'ω = dφ/dt,   ε = dω/dt,   v = ωR\nT = 2π/ω,   n = 1/T,   aτ = εR,   aₙ = ω²R',note:'Частоту в об/мин переводи в об/с: 600 об/мин = 10 об/с, ω = 2π·10 ≈ 63 рад/с.'}
    ],
    summary:'Кинематика описывает движение через радиус-вектор, скорость и ускорение. Путь — скаляр, перемещение — вектор; скорость направлена по касательной; ускорение раскладывается на тангенциальное и нормальное; вращение описывают угол, угловая скорость и угловое ускорение.'
  },
  2: {
    lead: 'Как силы изменяют движение тел и почему тело сохраняет скорость, пока равнодействующая сил равна нулю.',
    sections: [
      {h:'Первый закон Ньютона. Инерция',p:'Тело сохраняет состояние покоя или равномерного прямолинейного движения, если внешние воздействия не заставляют его изменить это состояние. Это свойство называется инертностью. Закон формулируется для инерциальных систем отсчёта.',formula:'ΣF = 0  ⇒  a = 0',note:'Нулевое ускорение означает постоянную скорость, а не обязательно покой.'},
      {h:'Инерциальные системы отсчёта',p:'Инерциальной называют систему, в которой свободное тело покоится или движется равномерно и прямолинейно. Система, связанная с Землёй, во многих инженерных задачах считается приближённо инерциальной: небольшими эффектами вращения Земли пренебрегают.'},
      {h:'Масса и сила',p:'Масса характеризует инертные свойства тела: чем больше масса, тем меньше изменение скорости при одном и том же воздействии. Сила — векторная мера механического воздействия. Она может изменять скорость тела или вызывать деформацию. Силу характеризуют модуль, направление и точка приложения.',formula:'[F] = Н = кг·м/с²'},
      {h:'Второй закон Ньютона',p:'Ускорение тела прямо пропорционально равнодействующей сил и обратно пропорционально массе. В уравнение входит именно векторная сумма всех сил, приложенных к телу. Закон применяют в инерциальной системе отсчёта.',formula:'ΣF⃗ = m a⃗',note:'Перед подстановкой выбери оси и разложи силы на проекции. Знаки проекций определяются выбранными положительными направлениями.'},
      {h:'Импульс тела',p:'Импульс — векторная величина, равная произведению массы на скорость. Его направление совпадает с направлением скорости. Общая формулировка второго закона Ньютона связывает силу со скоростью изменения импульса.',formula:'p⃗ = m v⃗     ·     F⃗ = dp⃗/dt',note:'При постоянной массе F⃗ = m a⃗. Единица импульса — кг·м/с.'},
      {h:'Принцип независимости действия сил',p:'Если на тело одновременно действуют несколько сил, результат определяется их равнодействующей — геометрической суммой. Каждая сила вносит свой вклад в ускорение.',formula:'F⃗рез = F⃗₁ + F⃗₂ + … + F⃗ₙ'},
      {h:'Третий закон Ньютона',p:'Тела взаимодействуют попарно: силы, с которыми два тела действуют друг на друга, равны по модулю, противоположны по направлению и лежат на одной прямой. Эти силы приложены к разным телам, поэтому не компенсируют друг друга в уравнении движения одного тела.',formula:'F⃗₁₂ = −F⃗₂₁',note:'Не путай пару действия и противодействия с двумя силами, приложенными к одному телу.'},
      {h:'Силы трения',p:'Трение препятствует относительному скольжению соприкасающихся поверхностей. Различают трение покоя, скольжения и качения; внутреннее трение возникает между слоями жидкости или газа. Для сухого трения скольжения в рассматриваемой модели сила пропорциональна нормальной реакции опоры.',formula:'Fтр = μN',note:'Коэффициент μ зависит от материалов и состояния поверхностей. Сила трения направлена против относительного движения или его возможного начала.'},
      {h:'Импульс системы и его сохранение',p:'Для системы тел различают внутренние силы взаимодействия между её частями и внешние силы со стороны окружающих тел. Внутренние силы попарно компенсируются в сумме для всей системы. Если равнодействующая внешних сил равна нулю, суммарный импульс системы остаётся постоянным.',formula:'P⃗ = Σ mᵢv⃗ᵢ = const  (ΣF⃗внеш = 0)',note:'Закон сохранения импульса применяют к замкнутой системе. Проекция импульса также сохраняется вдоль направления, в котором равнодействующая внешних сил равна нулю.'},
      {h:'Центр масс',p:'Центр масс — точка, положение которой отражает распределение массы системы. Для системы материальных точек его радиус-вектор равен взвешенному по массам среднему радиус-вектору.',formula:'r⃗с = (Σ mᵢr⃗ᵢ) / (Σ mᵢ)',note:'Для однородного симметричного тела центр масс совпадает с его геометрическим центром.'},
      {h:'Движение тела переменной массы',p:'Если масса тела меняется во время движения, как у ракеты при истечении газов, обычную запись второго закона Ньютона нужно дополнить реактивной силой. Направление ускорения зависит от направления выбрасываемого потока относительно ракеты.',formula:'m a⃗ = F⃗ + F⃗реакт\nпри F = 0:  v = u ln(m₀/m)',note:'Формула Циолковского относится к идеализированному нерелятивистскому движению при постоянной относительной скорости истечения газов.'}
    ],
    summary:'Динамика связывает движение с причинами его изменения. Для решения задач сначала выдели тело, изобрази все действующие на него силы, выбери оси, запиши второй закон Ньютона в проекциях. Для системы тел проверь, можно ли применить закон сохранения импульса.'
  },
  3: {
    lead: 'Работа описывает передачу энергии силами. Кинетическая и потенциальная энергии позволяют находить движение, а законы сохранения — анализировать столкновения.',
    sections: [
      {h:'Энергия, работа и мощность',p:'Работа постоянной силы при прямолинейном перемещении определяется проекцией силы на направление перемещения. Для переменной силы работу находят суммированием элементарных работ вдоль траектории. Работа положительна, если сила имеет составляющую по направлению движения, отрицательна — если против движения, и равна нулю при перпендикулярной силе.',formula:'A = F s cos α\nA = ∫ Fₛ ds'},
      {h:'Мощность',p:'Мощность характеризует скорость совершения работы. Мгновенная мощность равна скалярному произведению силы на скорость точки приложения силы.',formula:'N = dA/dt = F⃗ · v⃗\n1 Вт = 1 Дж/с'},
      {h:'Кинетическая энергия',p:'Кинетическая энергия — энергия механического движения. Работа равнодействующей сил изменяет кинетическую энергию тела. Значение зависит от массы и скорости, а также от выбора инерциальной системы отсчёта.',formula:'T = mv²/2\nAрез = ΔT'},
      {h:'Потенциальная энергия',p:'Потенциальная энергия характеризует взаимодействие тел и зависит от их взаимного расположения. Она вводится для потенциальных полей, в которых работа силы не зависит от траектории, а определяется начальным и конечным положениями. Нулевой уровень выбирают условно.',formula:'dA = −dP\nF⃗ = −grad P'},
      {h:'Потенциальная энергия тяжести и пружины',p:'Вблизи поверхности Земли при выбранном нулевом уровне P = mgh. Для упруго деформированной пружины потенциальная энергия растёт с квадратом деформации.',formula:'Pтяж = mgh\nPупр = kx²/2'},
      {h:'Закон сохранения механической энергии',p:'В консервативной системе, где действуют только консервативные силы, кинетическая и потенциальная энергии могут переходить друг в друга, но их сумма постоянна. При действии неконсервативных сил, например трения, механическая энергия изменяется; соответствующая энергия переходит в другие формы.',formula:'E = T + P = const\nΔE = Aнеконс'},
      {h:'Потенциальные кривые и равновесие',p:'График P(x) помогает определить допустимые положения тела: кинетическая энергия не может быть отрицательной, поэтому движение возможно там, где P(x) не превышает полной энергии E. В минимуме потенциальной энергии равновесие устойчиво: при малом смещении возникает возвращающая сила. В максимуме — неустойчиво.',formula:'T = E − P(x) ≥ 0'},
      {h:'Абсолютно упругий удар',p:'Удар — кратковременное взаимодействие тел. Если удар идеально упругий, после столкновения тела не сохраняют остаточной деформации, а кинетическая энергия возвращается в механическое движение. Для замкнутой системы сохраняются и импульс, и кинетическая энергия.',formula:'m₁v₁ + m₂v₂ = m₁v₁′ + m₂v₂′\nTдо = Tпосле'},
      {h:'Абсолютно неупругий удар',p:'При абсолютно неупругом ударе тела после столкновения движутся вместе. Сохраняется импульс системы, но часть кинетической энергии переходит во внутреннюю энергию и деформацию. Скорость общего движения находят из закона сохранения импульса.',formula:'v = (m₁v₁ + m₂v₂)/(m₁ + m₂)',note:'Векторные скорости учитывают со знаками или проекциями на выбранную ось.'},
      {h:'Коэффициент восстановления',p:'Степень упругости реального удара характеризуют отношением нормальных составляющих относительной скорости после и до удара. В идеализированных предельных случаях коэффициент равен нулю для абсолютно неупругого и единице для абсолютно упругого удара.',formula:'e = vₙ′ / vₙ\n0 ≤ e ≤ 1'}
    ],
    summary:'Для задач на работу и энергию определи, какие силы совершают работу и можно ли считать систему консервативной. Для столкновения сначала проверь сохранение импульса; кинетическую энергию дополнительно сохраняй только для абсолютно упругого удара.'
  }

};
const READER_EXTRA = {
4:['Механика твёрдого тела','Вращение задают угловые величины: угол, угловая скорость и угловое ускорение. Для точки на расстоянии r от оси линейная скорость и ускорение связаны с угловыми величинами.','Момент силы равен произведению силы на плечо и показывает её вращательное действие. Момент инерции зависит от массы и её распределения относительно оси.','Динамика вращения: сумма моментов внешних сил равна произведению момента инерции на угловое ускорение. При нулевом внешнем моменте сохраняется момент импульса.','v=ωr; aₜ=εr; aₙ=ω²r\nM=Fl; I=Σmᵢrᵢ²\nΣM=Iε; L=Iω'],
5:['Тяготение. Элементы теории поля','Любые два тела притягиваются с силой, пропорциональной произведению масс и обратно пропорциональной квадрату расстояния. Гравитационное поле описывают напряжённостью и потенциалом.','Для сферического тела вне его поля напряжённость направлена к центру. Потенциальная энергия отрицательна при нуле на бесконечности. Орбита возникает, когда гравитация обеспечивает центростремительное ускорение.','Законы Кеплера описывают орбиты планет; период обращения связан с большой полуосью. Космические скорости задают условия выхода на орбиту и ухода из поля.','F=Gm₁m₂/r²\ng=GM/r²; φ=−GM/r\nv₁=√(GM/r); T²/a³=const'],
6:['Элементы механики жидкостей','Давление в покоящейся жидкости растёт с глубиной. Закон Паскаля описывает передачу изменения давления, а закон Архимеда — выталкивающую силу, равную весу вытесненной среды.','Условия плавания определяются соотношением веса и силы Архимеда. При движении идеальной жидкости выполняется уравнение непрерывности: расход через сечения постоянен.','Уравнение Бернулли связывает давление, кинетическую энергию потока и высоту. Оно применимо для стационарного течения идеальной несжимаемой жидкости вдоль линии тока.','p=p₀+ρgh\nFₐ=ρжgVпогр\nS₁v₁=S₂v₂\np+ρv²/2+ρgh=const'],
7:['Специальная теория относительности','Постулаты Эйнштейна: законы физики одинаковы во всех инерциальных системах, а скорость света в вакууме постоянна. Пространственные и временные координаты преобразуются совместно.','Одновременность относительна. Движущиеся часы идут медленнее, а длина тела вдоль движения сокращается относительно наблюдателя.','Импульс и энергия растут с фактором Лоренца. При малых скоростях релятивистские формулы переходят в классические.','γ=1/√(1−v²/c²)\nΔt=γΔt₀; l=l₀/γ\np=γmv; E=γmc²'],
8:['Молекулярно-кинетическая теория идеальных газов','МКТ рассматривает вещество как множество частиц в непрерывном хаотическом движении. Давление возникает из-за ударов молекул о стенки. Температура связана со средней кинетической энергией поступательного движения.','Идеальный газ — модель, в которой собственным объёмом молекул и их взаимодействием между столкновениями пренебрегают. Состояние газа связывают давлением, объёмом и температурой.','Распределение Максвелла описывает разброс скоростей молекул. Средняя квадратичная скорость растёт с температурой и уменьшается с массой молекулы.','pV=νRT=NkT\np=(1/3)nm⟨v²⟩\n⟨Eₖ⟩=3kT/2'],
9:['Основы термодинамики','Внутренняя энергия включает микроскопические кинетические и потенциальные энергии частиц. Для идеального газа она зависит только от температуры. Теплота и работа — способы изменения внутренней энергии.','Первое начало термодинамики выражает сохранение энергии: подведённая теплота идёт на изменение внутренней энергии и работу системы. Для изохорного процесса работа равна нулю, для изотермического идеального газа не меняется внутренняя энергия.','Второе начало задаёт направление самопроизвольных процессов. Тепловая машина превращает часть полученной теплоты в работу; её КПД ограничен температурой нагревателя и холодильника.','Q=ΔU+A\nAизоб=pΔV; Qизох=νCᵥΔT\nη=1−Q₂/Q₁; ηКарно=1−T₂/T₁'],
10:['Реальные газы, жидкости и твёрдые тела','Реальные газы отличаются от идеальных конечным размером молекул и межмолекулярными силами. Поправки Ван-дер-Ваальса учитывают притяжение и собственный объём частиц.','Жидкости обладают поверхностным натяжением: поверхность стремится уменьшить площадь. Смачивание и капиллярность зависят от взаимодействия жидкости с поверхностью.','Фазовые переходы сопровождаются скрытой теплотой. Кристаллические тела имеют дальний порядок, аморфные — ближний; структура влияет на механические и тепловые свойства.','(p+aν²/V²)(V−νb)=νRT\nF=σl; h=2σcosθ/(ρgr)\nQ=λm'],
11:['Электростатика','Электрический заряд бывает двух знаков, сохраняется и квантуется. Закон Кулона задаёт силу взаимодействия точечных зарядов; электрическое поле описывают напряжённостью.','Для нескольких зарядов действует принцип суперпозиции. Потенциал — энергетическая характеристика поля, напряжение — разность потенциалов. Теорема Гаусса связывает поток поля с зарядом внутри замкнутой поверхности.','Проводник в электростатическом равновесии имеет нулевое поле внутри. Конденсатор накапливает заряд и энергию электрического поля; ёмкость зависит от геометрии и диэлектрика.','F=k|q₁q₂|/r²\nE=F/q; φ=W/q\nC=q/U; W=CU²/2'],
12:['Постоянный электрический ток','Сила тока — заряд, проходящий через сечение за единицу времени. Закон Ома связывает ток, напряжение и сопротивление; сопротивление проводника зависит от материала, длины и площади сечения.','Последовательное соединение сохраняет ток во всех элементах, параллельное — напряжение на ветвях. Для разветвлённых цепей применяют правила Кирхгофа.','Источник характеризуют ЭДС и внутренним сопротивлением. Электрическая энергия преобразуется в тепло и другие виды энергии; выделение теплоты описывает закон Джоуля—Ленца.','I=dq/dt; I=U/R\nR=ρl/S; I=ℰ/(R+r)\nP=UI; Q=I²Rt'],
13:['Электрические токи в металлах, вакууме и газах','В металлах ток создают свободные электроны; сопротивление связано с рассеянием носителей и зависит от температуры. В вакууме ток возможен при эмиссии электронов с катода.','В полупроводниках ток переносят электроны и дырки. Примеси создают донорную или акцепторную проводимость, а температура меняет концентрацию носителей.','В электролитах ток переносится ионами и сопровождается электролизом. В газах ток возникает после ионизации; различают самостоятельные и несамостоятельные разряды.','R=R₀[1+αΔT]\nm=kIt'],
14:['Магнитное поле','Магнитное поле создаётся токами и движущимися зарядами. Его основной характеристикой является магнитная индукция B. На проводник с током действует сила Ампера, на движущийся заряд — сила Лоренца.','Магнитная сила перпендикулярна скорости заряда и не совершает работы. Поэтому в однородном поле при поперечном влёте частица движется по окружности.','Магнитный поток зависит от поля, площади и ориентации поверхности. Поля токов находят с помощью закона Био—Савара и теоремы о циркуляции.','FА=BIl sinα\nFЛ=|q|vB sinα\nr=mv/(|q|B); Φ=BS cosα'],
15:['Электромагнитная индукция','Индукционный ток появляется при изменении магнитного потока через контур. Закон Фарадея связывает ЭДС с быстротой изменения потока; знак определяется правилом Ленца.','Движущийся проводник в магнитном поле может создавать ЭДС движения. Изменение собственного тока катушки вызывает самоиндукцию, препятствующую изменению тока.','Магнитное поле катушки обладает энергией. Индукция лежит в основе генераторов, трансформаторов и многих устройств преобразования энергии.','ℰᵢ=−dΦ/dt\nℰ=Blv; ℰс=−L·dI/dt\nWм=LI²/2'],
16:['Магнитные свойства вещества','Магнитные свойства связаны с магнитными моментами электронов и атомов. Диамагнетики слабо ослабляют поле, парамагнетики слабо усиливают его.','В ферромагнетиках существуют домены — области упорядоченной намагниченности. Внешнее поле меняет размеры и ориентацию доменов, вызывая сильный отклик.','Гистерезис означает зависимость намагниченности от предыстории поля. Остаточная намагниченность и коэрцитивная сила важны для постоянных магнитов; выше точки Кюри ферромагнетизм исчезает.','B=μ₀(H+M)'],
17:['Основы теории Максвелла','Изменяющееся магнитное поле порождает вихревое электрическое поле. Изменяющееся электрическое поле, в свою очередь, участвует в создании магнитного поля — это учитывает ток смещения.','Уравнения Максвелла объединяют электрические и магнитные явления: описывают источники полей, отсутствие магнитных монополей и связь переменных полей.','Электромагнитное поле переносит энергию и импульс. Поток энергии характеризуется вектором Пойнтинга.','S⃗=E⃗×H⃗\nw=ε₀E²/2+B²/(2μ₀)'],
18:['Механические и электромагнитные колебания','Гармонические колебания описываются синусоидой; амплитуда задаёт размах, период — длительность цикла, частота — число циклов за секунду. Пружинный и математический маятники имеют собственные периоды.','В реальных системах сопротивление вызывает затухание. Вынужденные колебания поддерживаются внешней периодической силой; при близости частот возникает резонанс.','В LC-контуре энергия переходит между электрическим полем конденсатора и магнитным полем катушки. Сходство уравнений позволяет использовать общие методы анализа.','x=A cos(ωt+φ)\nTпруж=2π√(m/k); Tмаят=2π√(l/g)\nωLC=1/√(LC)'],
19:['Упругие волны','Механическая волна переносит возмущение и энергию через упругую среду, тогда как частицы среды колеблются около равновесия. Волны бывают продольными и поперечными.','Длина волны — расстояние между точками одинаковой фазы. Скорость волны связана с длиной волны и частотой; бегущая волна имеет фазу, зависящую от координаты и времени.','Звук — упругая волна в среде. Высота тона связана с частотой, громкость — с интенсивностью, тембр — со спектром. Эффект Доплера меняет наблюдаемую частоту при относительном движении.','λ=vT=v/ν\nξ=A cos(ωt−kx+φ₀)\nk=2π/λ'],
20:['Электромагнитные волны','Переменные электрическое и магнитное поля поддерживают распространение электромагнитной волны. В плоской волне поля взаимно перпендикулярны и перпендикулярны направлению распространения.','В вакууме скорость равна скорости света. В веществе скорость и длина волны меняются, но частота при переходе границы остаётся прежней.','Электромагнитный спектр включает радиоволны, микроволны, инфракрасное, видимое, ультрафиолетовое, рентгеновское и гамма-излучение. Волны переносят энергию и импульс.','c=1/√(ε₀μ₀)\nv=c/n; E=cB'],
21:['Геометрическая и электронная оптика','Геометрическая оптика использует модель лучей. Законы отражения и преломления позволяют строить изображения и рассчитывать ход света в линзах и оптических приборах.','Тонкая линза формирует действительное или мнимое изображение. Полное внутреннее отражение возможно при переходе из среды с большим показателем преломления в среду с меньшим.','Электронная оптика управляет пучками электронов электрическими и магнитными полями: ускоряет, отклоняет и фокусирует их.','n₁sinα=n₂sinβ\n1/f=1/a+1/b\nsinαкр=n₂/n₁'],
22:['Интерференция света','Интерференция возникает при наложении когерентных волн и приводит к устойчивому чередованию максимумов и минимумов интенсивности. Разность фаз связана с разностью хода.','В опыте Юнга две щели создают когерентные волны. Шаг полос зависит от длины волны, расстояния до экрана и расстояния между щелями.','Интерференция в тонких плёнках зависит от оптической разности хода и фазовых скачков при отражении. Её применяют в измерениях и просветляющих покрытиях.','Δ=mλ — максимум\nΔ=(m+1/2)λ — минимум\nΔx=λL/d'],
23:['Дифракция света','Дифракция — отклонение от геометрического распространения волн при прохождении через отверстия и около препятствий. Она заметна, когда размеры сравнимы с длиной волны.','Дифракционная решётка создаёт узкие максимумы, положение которых зависит от периода решётки и длины волны. Поэтому решётки используют для спектрального анализа.','Дифракция ограничивает разрешение оптических приборов. Рентгеновская дифракция позволяет исследовать кристаллическую структуру.','d sinθ=mλ\na sinθ=mλ\nθmin≈1,22λ/D'],
24:['Взаимодействие света с веществом','Свет в веществе может поглощаться, рассеиваться, отражаться и преломляться. Поглощение ослабляет интенсивность пучка по мере прохождения слоя.','Дисперсия означает зависимость показателя преломления от частоты. Поэтому белый свет разлагается в спектр, а спектры излучения и поглощения позволяют исследовать состав вещества.','Люминесценция — излучение после возбуждения, не сводящееся к обычному тепловому свечению. Флуоресценция быстро прекращается после снятия возбуждения, фосфоресценция может продолжаться.','I=I₀e^(−αl)'],
25:['Поляризация света','Поляризация характеризует направление колебаний электрического вектора световой волны. Естественный свет неполяризован, линейно поляризованный имеет выделенное направление колебаний.','Поляризатор выделяет компоненту колебаний вдоль своей оси. Анализатор проверяет состояние поляризации; интенсивность зависит от угла между осями.','Поляризация возникает также при отражении и двойном лучепреломлении. Угол Брюстера соответствует полной линейной поляризации отражённого света.','I=I₀cos²φ\ntanθБ=n₂/n₁'],
26:['Квантовая природа излучения','Энергия электромагнитного излучения передаётся порциями — фотонами. Энергия фотона пропорциональна частоте, импульс обратно пропорционален длине волны.','Фотоэффект подтверждает квантовую передачу энергии: фотон расходуется на работу выхода и кинетическую энергию электрона. Эффект Комптона показывает изменение длины волны при рассеянии фотона на электроне.','Тепловое излучение описывают законы Планка, Вина и Стефана—Больцмана. Давление света связано с передачей импульса фотонов поверхности.','E=hν=hc/λ; p=h/λ\nhν=Aвых+mv²/2\nλmaxT=b; R=σT⁴'],
27:['Теория атома водорода по Бору','Модель Бора вводит стационарные состояния атома: электрон на разрешённой орбите не излучает энергию. Излучение и поглощение происходят при переходах между уровнями.','Момент импульса орбиты квантуется. Радиусы орбит растут как n², а энергии связанных состояний пропорциональны −1/n².','Разность энергий уровней определяет энергию фотона. Спектральные линии водорода группируются в серии с общим нижним уровнем переходов.','mvr=nℏ\nrₙ=a₀n²; Eₙ=−13,6 эВ/n²\n1/λ=R(1/m²−1/n²)'],
28:['Элементы квантовой механики','Волновые свойства микрочастиц выражаются длиной волны де Бройля. Соотношение неопределённостей ограничивает одновременную точность координаты и импульса.','Состояние описывается волновой функцией, квадрат модуля которой задаёт плотность вероятности. Уравнение Шрёдингера и граничные условия определяют разрешённые состояния и энергии.','Для связанных состояний энергия часто дискретна. Туннельный эффект позволяет частице проходить через потенциальный барьер с ненулевой вероятностью.','λ=h/p\nΔxΔpₓ≥ℏ/2\nρ=|ψ|²; iℏ∂ψ/∂t=Ĥψ'],
29:['Физика атомов и молекул','Состояния электронов в атоме задаются квантовыми числами. Принцип Паули запрещает двум электронам иметь одинаковый набор четырёх квантовых чисел.','Заполнение оболочек и подуровней определяет электронную конфигурацию и периодические свойства элементов. Переходы между уровнями создают характерные атомные спектры.','В молекулах существуют электронные, колебательные и вращательные уровни. Вынужденное излучение при инверсной населённости лежит в основе работы лазера.','n=1,2,…; l=0,…,n−1\nmₗ=−l,…,+l'],
30:['Элементы квантовой статистики','Одинаковые квантовые частицы неразличимы. По спину их делят на бозоны и фермионы: фермионы подчиняются принципу Паули, бозоны могут совместно занимать одно состояние.','Распределение Ферми—Дирака описывает фермионы, а Бозе—Эйнштейна — бозоны. При разреженном газе и высокой температуре оба переходят к классическому пределу.','Квантовая статистика объясняет свойства электронного газа в металлах, тепловое излучение и коллективные квантовые состояния вещества.','n̄F=1/[e^((ε−μ)/kT)+1]\nn̄B=1/[e^((ε−μ)/kT)−1]'],
31:['Элементы физики твёрдого тела','Кристаллическая решётка задаёт периодическое расположение частиц. Дефекты и примеси нарушают идеальную периодичность и влияют на прочность, диффузию и проводимость.','Энергетические зоны возникают из расщепления атомных уровней в кристалле. Ширина запрещённой зоны и её заполнение определяют, будет ли вещество металлом, диэлектриком или полупроводником.','В полупроводниках ток переносят электроны и дырки; легирование создаёт n- и p-типы. Сверхпроводимость характеризуется нулевым сопротивлением и эффектом Мейснера ниже критической температуры.','σ=ne²τ/m'],
32:['Физика атомного ядра','Ядро состоит из протонов и нейтронов. Зарядовое число Z задаёт число протонов, массовое число A — общее число нуклонов. Массовый дефект связан с энергией связи.','Радиоактивный распад происходит самопроизвольно по экспоненциальному закону. Различают альфа-, бета- и гамма-превращения; у каждого сохраняются соответствующие характеристики ядра.','В ядерных реакциях энергия выделяется или поглощается в соответствии с разностью масс. Деление тяжёлых ядер и синтез лёгких лежат в основе ядерной энергетики и звёздных процессов.','A=Z+N; Eсв=Δmc²\nN=N₀e^(−λt); T₁/₂=ln2/λ\nQ=Δmc²'],
33:['Физика элементарных частиц','Фундаментальные частицы включают кварки и лептоны; взаимодействия описываются полями и частицами-переносчиками. Протоны и нейтроны — составные адроны.','Античастицы имеют ту же массу, но противоположные некоторые квантовые числа. При аннигиляции частица и античастица превращаются в другие частицы и излучение.','В реакциях частиц проверяют сохранение энергии, импульса, электрического заряда и квантовых чисел. Ускорители создают столкновения, детекторы регистрируют продукты распада.','E=mc²; p=γmv']
};
for(const [k,v] of Object.entries(READER_EXTRA)){
 const [title,p1,p2,p3,formula]=v;
 const s0=p1.split(/(?<=[.!?])\s/)[0], rest=p1.slice(s0.length).trim();
 READER_NOTES[k]={lead:s0,sections:[
 {h:'Основные понятия и физическая модель',p:rest||p1},
 {h:'Законы и закономерности',p:p2},
 {h:'Применение и важные следствия',p:p3},
 {h:'Основные формулы главы',p:'Используй формулы после определения физических величин, условий применимости и выбранных направлений отсчёта.',formula}
 ],summary:p3+' При решении задач сначала определи физическую модель, затем выпиши закон и проверь единицы измерения.'};
}
let readerFontSize = Number(localStorage.getItem('f2-reader-font') || 17);
function readerStyles(){return `<style>
.reader-shell{--reader-size:${readerFontSize}px;color:var(--text);max-width:820px;margin:0 auto}
.reader-top{position:sticky;top:0;z-index:8;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 12px;margin:-4px -4px 14px;background:color-mix(in srgb,var(--bg) 90%,transparent);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}
.reader-top a,.reader-top button,.reader-bottom button{border:1px solid var(--line);background:var(--card);color:var(--text);border-radius:12px;padding:9px 12px;font-weight:700;text-decoration:none}
.reader-progress{height:3px;background:var(--line);border-radius:4px;overflow:hidden;flex:1}.reader-progress i{display:block;height:100%;width:0;background:#64d7d9}
.reader-cover{padding:22px;border-radius:22px;background:linear-gradient(135deg,#172c45,#26365b 60%,#17434a);color:#f4f8ff;margin-bottom:16px}
.reader-cover small{letter-spacing:1.7px;color:#9de2e6;font-weight:800}.reader-cover h1{font-size:clamp(25px,6vw,38px);line-height:1.1;margin:12px 0}.reader-cover p{color:#c7d6e4;line-height:1.55;margin:0}
.reader-chapter{display:flex;align-items:center;gap:14px;padding:15px;margin:9px 0;border:1px solid var(--line);border-radius:16px;background:var(--card);color:var(--text);text-decoration:none}
.reader-chapter .num{width:42px;height:42px;display:grid;place-items:center;border-radius:13px;background:#213c50;color:#a5e6e7;font-weight:850}
.reader-chapter b{display:block;line-height:1.3}.reader-chapter small{display:block;color:var(--muted);margin-top:5px}
.reader-page{font-size:var(--reader-size);line-height:1.72;letter-spacing:.005em}
.reader-page h2{font-size:1.18em;line-height:1.3;margin:26px 0 8px;letter-spacing:-.02em}
.reader-page p{margin:0 0 12px;color:var(--text)}
.reader-formula{margin:13px 0 16px;padding:16px 12px;text-align:center;border:1px solid #426477;border-radius:15px;background:linear-gradient(135deg,#12283a,#172d40);color:#b9f1ed;font-size:1.05em;font-weight:750;letter-spacing:.02em;overflow-wrap:anywhere}
.reader-note{padding:12px 14px;border-left:3px solid #e7b45b;background:rgba(231,180,91,.09);border-radius:0 12px 12px 0;color:var(--muted);font-size:.91em;margin:14px 0}
.reader-figure{margin:18px 0;padding:14px;border:1px solid var(--line);border-radius:17px;background:var(--card)}
.reader-figure svg{display:block;width:100%;height:auto;max-height:210px}
.reader-art{padding:0;overflow:hidden}.reader-art svg{max-height:none;aspect-ratio:640/220}.reader-art figcaption{padding:10px 14px 12px}
.reader-figure figcaption{text-align:center;color:var(--muted);font-size:.8em;margin-top:8px}
.reader-summary{margin:22px 0;padding:18px;border-radius:18px;background:linear-gradient(135deg,rgba(76,180,171,.14),rgba(87,116,190,.12));border:1px solid rgba(90,190,180,.25)}
.reader-page{padding-bottom:108px}
.reader-bottom{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(66px + env(safe-area-inset-bottom));z-index:30;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:8px;width:min(820px,100%);padding:9px 12px;background:color-mix(in srgb,var(--bg) 94%,transparent);backdrop-filter:blur(16px);border-top:1px solid var(--line);box-shadow:0 -8px 24px rgba(0,0,0,.18)}
.reader-bottom button{min-height:44px;border:1px solid #3c6174;border-radius:13px;background:linear-gradient(135deg,#1b354b,#203b50);color:#e9f8fb;font-weight:800;white-space:nowrap}.reader-bottom button:last-child{background:linear-gradient(120deg,#176b70,#248f87);border-color:#3ab8a7}.reader-page-count{color:var(--muted);font:800 11px var(--numbers);white-space:nowrap}
@media(max-width:600px){.reader-cover{padding:19px}.reader-top{margin:0 -10px 12px}.reader-page{line-height:1.7}.reader-bottom{bottom:calc(64px + env(safe-area-inset-bottom));padding:8px 9px;gap:6px}.reader-bottom button{padding:9px 7px;font-size:12px}}
</style>`}
function vReader(){
 frame('Читатель',{back:true,sub:'Конспекты по курсу Т. И. Трофимовой'});
 const chapters=CHAPTERS;
 setMain(readerStyles()+`<div class="reader-shell"><section class="reader-cover"><small>ФИЗИКА · БОЛЬШОЙ ЧИТАТЕЛЬ</small><h1>Читай и понимай</h1><p>Удобные конспекты по главам: определения, физический смысл, формулы и схемы. Размер текста адаптируется под экран.</p></section><div class="reader-top"><a href="#book">← Учебник</a><div class="reader-progress"><i style="width:3%"></i></div><button data-act="readerFont" data-delta="-1" aria-label="Уменьшить шрифт">A−</button><button data-act="readerFont" data-delta="1" aria-label="Увеличить шрифт">A+</button></div><h2 class="sec">Содержание</h2>${chapters.map(c=>`<a class="reader-chapter" href="#read-${c.n}"><span class="num">${String(c.n).padStart(2,'0')}</span><span><b>${esc(c.title)}</b><small>Глава ${c.n} · § ${c.a}–${c.b} · ${READER_NOTES[c.n]?'Конспект готов':'В очереди на конспект'}</small></span>${ic('chevron-right')}</a>`).join('')}</div>`);
}
// рисунок к главе в читателе: схема сил — для динамики, для остальных — иллюстрация главы
const ROMAN = ['', 'I', 'II', 'III', 'IV', 'V', 'VI', 'VII'];
const READER_FORCE_FIG = `<figure class="reader-figure"><svg viewBox="0 0 640 190" role="img" aria-label="Схема действия сил на тело"><defs><marker id="rarr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#6fe0d7"/></marker></defs><rect x="250" y="68" width="110" height="65" rx="12" fill="#24475c" stroke="#8bd9df" stroke-width="3"/><path d="M305 68V22" stroke="#6fe0d7" stroke-width="4" marker-end="url(#rarr)"/><path d="M360 100H470" stroke="#e9b45d" stroke-width="4" marker-end="url(#rarr)"/><path d="M305 133V174" stroke="#9b8df4" stroke-width="4" marker-end="url(#rarr)"/><text x="320" y="105" text-anchor="middle" fill="#f4fbff" font-size="17">m</text><text x="323" y="16" text-anchor="middle" fill="#6fe0d7" font-size="15">N</text><text x="480" y="105" fill="#e9b45d" font-size="15">F</text><text x="323" y="188" text-anchor="middle" fill="#9b8df4" font-size="14">mg</text></svg><figcaption>Схема сил, действующих на тело. В задаче учитывают все силы и их направления.</figcaption></figure>`;
const readerFig = c => c.n === 2 ? READER_FORCE_FIG : `<figure class="reader-figure reader-art">${chapterArt(c, 640, 220)}<figcaption>Глава ${c.n} · ${esc(c.title)}</figcaption></figure>`;
function vReaderChapter(r){
 const c=CHAPTERS[r.ch-1], n=READER_NOTES[r.ch];
 if(!c){location.hash='reader';return}
 if(!n){location.hash='reader';return}
 frame(c.title,{back:true,sub:'Глава '+c.n+' · § '+c.a+'–'+c.b});
 const cards=n.sections.map((x,i)=>`<section><h2>${i+1}. ${esc(x.h)}</h2><p>${esc(x.p)}</p>${x.formula?`<div class="reader-formula">${esc(x.formula)}</div>`:''}${x.note?`<div class="reader-note"><b>Важно:</b> ${esc(x.note)}</div>`:''}</section>`).join('');
 setMain(readerStyles()+`<article class="reader-shell reader-page" id="reader-article"><div class="reader-top"><a href="#reader">← Содержание</a><div class="reader-progress"><i id="reader-progress-fill"></i></div><button data-act="readerFont" data-delta="-1">A−</button><button data-act="readerFont" data-delta="1">A+</button></div><section class="reader-cover"><small>ЧАСТЬ ${ROMAN[c.part]} · ${esc(PARTS[c.part - 1].title.toUpperCase())}</small><h1>${esc(c.title)}</h1><p>${esc(n.lead)}</p></section><div class="reader-video"><div class="reader-video-h">${ic('clapperboard')}<b>Видео-конспект главы</b><small id="rv-len"></small></div>${rvBox('Видео-конспект: ' + c.title)}</div>${readerFig(c)}${cards}<section class="reader-summary"><b>Главное в главе</b><p>${esc(n.summary)}</p></section><div class="reader-bottom"><button data-act="readerPrev" data-v="${Math.max(1,r.ch-1)}" ${r.ch===1?"disabled":""}>← Назад</button><span class="reader-page-count">${r.ch} / 33</span><button data-act="readerNext" data-v="${Math.min(33,r.ch+1)}" ${r.ch===33?"disabled":""}>Далее →</button></div></article>`);
 { const sc = rvChapterScenes(c.n); rvInit(sc, c.n, null); const len = $('#rv-len'); if (len && RV) len.textContent = '≈ ' + Math.max(1, Math.round(RV.dur / 60)) + ' мин · ' + sc.length + ' сцен'; }
 const article=document.getElementById('reader-article'),main=document.getElementById('main'); if(article&&main){const update=()=>{const max=Math.max(1,article.offsetTop+article.scrollHeight-main.clientHeight);const p=Math.min(100,Math.max(0,Math.round(main.scrollTop/max*100)));const f=document.getElementById('reader-progress-fill');if(f)f.style.width=p+'%';};main.addEventListener('scroll',update,{passive:true});update();}
}

/* ---------- Глава ---------- */
function vChapter(r) {
  const ch = CHAPTERS[r.ch - 1], C1 = CONTENT[r.ch]; if (!C1) { location.hash = 'book'; return; }
  frame(`Глава ${ch.n}`, { back: true });
  const nowI = C1.lessons.findIndex((_, k) => !lessonDone(ch.n, k + 1));
  const nodes = C1.lessons.map((L, k) => {
    const d = S.lessons[lessonKey(ch.n, k + 1)], now = k === nowI;
    return `<a class="node${d ? ' done' : ''}${now ? ' now' : ''}" href="#l${ch.n}-${k + 1}"><span class="dot">${d ? ic('check') : k + 1}</span><span class="nl"><small>${esc(L.par)}</small><b>${esc(L.title)}</b>${d ? stars(d.stars) : `<small>${now ? 'следующий урок' : esc(L.lead)}</small>`}</span></a>`;
  }).join('<span class="conn"></span>');
  const bb = S.boss[ch.n];
  setMain(`<section class="chead"><div class="cart big">${chapterArt(ch, 360, 170)}</div><div class="chx"><small>Часть ${ch.part} · § ${ch.a}–${ch.b}</small><h1>${esc(ch.title)}</h1><div class="pbar"><i style="width:${chapterProgress(ch.n) * 100}%"></i></div></div></section>` +
    `<section class="path">${nodes}<span class="conn"></span><button class="node boss${bb >= 80 ? ' done' : ''}" data-act="boss" data-ch="${ch.n}"><span class="dot">${ic('swords')}</span><span class="nl"><small>финал главы · ${C1.boss.length} вопросов</small><b>Финальное испытание</b><small>${bb != null ? `лучший результат ${bb}%` : 'порог 80% · +150 XP'}</small></span></button></section>` +
    `<h2 class="sec">Учёные главы</h2><div class="sci">${C1.scientists.map(x => `<div class="scard${S.sci.includes(x.id) ? '' : ' locked'}"><b>${esc(x.name)}</b><small>${esc(x.years)}</small><p>${S.sci.includes(x.id) ? esc(x.fact) : 'Откроется после финального испытания главы'}</p></div>`).join('')}</div>` +
    (chExam(ch.n).length ? `<button class="btn line wide mt" data-act="chQuiz" data-ch="${ch.n}">${ic('dumbbell')}Вопросы экзамена по главе · ${chExam(ch.n).length}</button>` : '') +
    (READER_NOTES[ch.n] ? `<a class="btn line wide mt" href="#read-${ch.n}">${ic('book-open')}Конспект главы в читателе</a>` : ''));
}
const stars = n => `<span class="stars">${[1, 2, 3].map(i => ic('star', i <= n ? 'on' : '')).join('')}</span>`;

/* ---------- Урок: Ролик · Конспект · Практика · Проверка ---------- */
const STEPS = [['video', 'Ролик', 'clapperboard'], ['cards', 'Конспект', 'layers'], ['sim', 'Практика', 'sliders-horizontal'], ['quiz', 'Проверка', 'circle-check']];
const curStep = {};
// шаги урока: ролик — свой (L.video) или собранный из карточек; практика — симуляция или «Найди пару»
const lessonSteps = L => STEPS.filter(([k]) => k === 'video' ? !!(L.video || (L.cards && L.cards.length)) : k === 'sim' ? !!(L.sim || (L.pairs && L.pairs.length >= 4)) : true);
function vLesson(r) {
  const ch = CHAPTERS[r.ch - 1], C1 = CONTENT[r.ch], L = C1 && C1.lessons[r.li - 1]; if (!L) { location.hash = 'c' + r.ch; return; }
  const steps = lessonSteps(L), key = lessonKey(r.ch, r.li), done = S.steps[key] || {};
  let st = curStep[key] || steps[0][0]; if (!steps.some(s => s[0] === st)) st = steps[0][0];
  frame(esc(L.title), { back: true, sub: `Глава ${ch.n} · ${esc(L.par)}` });
  const tabs = `<div class="steps" style="grid-template-columns:repeat(${steps.length},1fr)">${steps.map(([k, t, i]) => `<button data-act="step" data-v="${k}" class="${k === st ? 'on' : ''}${done[k] ? ' ok' : ''}">${ic(done[k] ? 'check' : i)}<span>${t}</span></button>`).join('')}</div>`;
  if (st === 'video' && L.video && !isScriptVideo(L)) { setMain(tabs + videoBox(r.ch, L)); videoInit(r.ch, r.li, L); }
  else if (st === 'video') { setMain(tabs + rvBox(L.title) + nextStepBtn('video', L)); rvInit(L.video ? rvVideoScenes(r.ch, L) : rvLessonScenes(r.ch, L), r.ch, () => stepDone(key, 'video', 10)); }
  else if (st === 'cards') { setMain(tabs + cardsBox(L)); cardsInit(key, L); cardFigsDraw(); }
  else if (st === 'sim') { setMain(tabs + `<div id="simbox"></div>`); if (L.sim) simStart(SIMS[L.sim], key, L); else pairStart(L, key); }
  else setMain(tabs + `<section class="card center"><div class="qic">${ic('circle-check', 'big')}</div><b class="h">Проверка по уроку</b><p class="mute">${plural(L.quiz.length, 'вопрос', 'вопроса', 'вопросов')} с объяснениями. Верные ответы подряд — комбо и больше опыта.${S.lessons[key] ? ` Лучший результат: ${S.lessons[key].best}%.` : ''}</p><button class="btn wide" data-act="lessonQuiz" data-ch="${r.ch}" data-li="${r.li}">Начать проверку</button></section>`);
}
function stepDone(key, k, xp) { const d = S.steps[key] || (S.steps[key] = {}); if (!d[k]) { d[k] = 1; save(); addXP(xp); } }
const nextStepBtn = (k, L) => { const S2 = lessonSteps(L), i = S2.findIndex(s => s[0] === k), n = S2[i + 1]; return n ? `<button class="btn wide mt" data-act="step" data-v="${n[0]}">Дальше: ${n[1]} ${ic('chevron-right')}</button>` : ''; };

/* ---------- ролик: сцены на холсте + озвучка, синхронно ---------- */
let V = null;
function videoBox(ch, L) {
  return `<section class="vid"><div class="vwrap"><canvas id="vc" width="960" height="540"></canvas><button class="vplay" data-act="vToggle" aria-label="Смотреть">${ic('play')}</button></div>` +
    `<div class="vctl"><button class="vb" data-act="vToggle" aria-label="Пауза/смотреть" id="vpp">${ic('play')}</button><div class="vseek" id="vseek"><i></i></div><span id="vtime">0:00</span><button class="vb" data-act="vCc" aria-label="Субтитры" id="vcc">${ic('captions')}</button></div>` +
    `<p class="vsub" id="vsub">${esc(L.video[0].t)}</p></section>` + nextStepBtn('video', L);
}
function videoInit(ch, li, L) {
  const id = `ch${ch}-l${li}`, meta = (typeof VOICE !== 'undefined' && VOICE[id]) || null;
  // без озвучки — свои часы по длине текста
  const starts = meta ? meta.starts : (() => { let t = 0; return L.video.map(s => { const a = t; t += Math.max(4, s.t.length / 14); return a; }); })();
  const dur = meta ? meta.dur : starts[starts.length - 1] + Math.max(4, L.video[L.video.length - 1].t.length / 14);
  V = { L, key: lessonKey(ch, li), starts, dur, t: 0, playing: false, audio: null, last: 0, cc: S.cc !== 0, raf: 0 };
  if (meta) { // файл целиком в память: перемотка работает на любом хостинге и без интернета
    const A = V.audio = new Audio(); A.addEventListener('ended', vEnd);
    V.ready = fetch('audio/' + id + '.mp3').then(r => { if (!r.ok) throw new Error(r.status); return r.blob(); }).then(b => { A.src = URL.createObjectURL(new Blob([b], { type: 'audio/mpeg' })); }).catch(() => { if (V && V.audio === A) V.audio = null; });
  }
  $('#vsub').hidden = !V.cc; vDraw();
}
function vSeg(t) { let i = 0; while (i + 1 < V.starts.length && t >= V.starts[i + 1]) i++; const a = V.starts[i], b = i + 1 < V.starts.length ? V.starts[i + 1] : V.dur; return { i, p: Math.min(1, (t - a) / (b - a)), lt: t - a }; }
function vDraw() {
  const cv = $('#vc'); if (!cv || !V) return; const c = cv.getContext('2d'), { i, p, lt } = vSeg(V.t);
  SCENES[V.L.video[i].s](c, 960, 540, p, lt);
  const sb = $('#vsub'); if (sb && sb.dataset.i !== String(i)) { sb.innerHTML = vx(V.L.video[i].t); sb.dataset.i = i; }
  const f = Math.min(1, V.t / V.dur); $('#vseek i').style.width = f * 100 + '%'; $('#vtime').textContent = mmss(V.t) + ' / ' + mmss(V.dur);
}
function vLoop(now) {
  if (!V || !V.playing) return;
  if (V.audio) V.t = V.audio.currentTime; else { V.t += (now - V.last) / 1000; V.last = now; if (V.t >= V.dur) { V.t = V.dur; vDraw(); return vEnd(); } }
  vDraw(); V.raf = requestAnimationFrame(vLoop);
}
async function vToggle() {
  if (!V) return;
  if (!V.playing && V.ready) { $('#vtime').textContent = 'загрузка…'; const v0 = V; await V.ready; if (V !== v0) return; }
  V.playing = !V.playing;
  if (V.t >= V.dur - 0.05) { V.t = 0; if (V.audio) V.audio.currentTime = 0; }
  if (V.playing) { V.last = performance.now(); if (V.audio) V.audio.play().catch(() => { V.audio = null; }); V.raf = requestAnimationFrame(vLoop); } else if (V.audio) V.audio.pause();
  $('.vplay').hidden = V.playing; $('#vpp').innerHTML = ic(V.playing ? 'pause' : 'play');
}
function vEnd() { if (!V) return; V.playing = false; $('.vplay') && ($('.vplay').hidden = false); $('#vpp') && ($('#vpp').innerHTML = ic('rotate-ccw')); stepDone(V.key, 'video', 10); }
function vSeek(e) { const b = $('#vseek'); if (!b || !V) return; const r = b.getBoundingClientRect(), f = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)); V.t = f * V.dur; if (V.audio) V.audio.currentTime = V.t; vDraw(); }
function stopLoops() { if (typeof sbStop === 'function') sbStop(); if (typeof rvStop === 'function') rvStop(); if (V) { V.playing = false; cancelAnimationFrame(V.raf); if (V.audio) V.audio.pause(); V = null; } if (G && G.raf) cancelAnimationFrame(G.raf); if (LAB && LAB.raf) { cancelAnimationFrame(LAB.raf); LAB.raf=0; LAB.run=false; LAB.paused=false; } }

/* ---------- карточки конспекта: листаются пальцем ---------- */
const KIND = { idea: ['Главное', 'var(--blue)'], def: ['Определение', 'var(--mint)'], formula: ['Формула', 'var(--gold)'], trap: ['Ловушка', 'var(--pink)'], ex: ['Пример', 'var(--violet)'] };
function cardsBox(L) {
  return `<div class="cards" id="cards">${L.cards.map((k, i) => `<article class="kcard"><span class="kind" style="--kc:${KIND[k.k][1]}">${KIND[k.k][0]}</span><h3>${vx(k.h)}</h3>${k.fig && FIGS[k.fig] ? FIGS[k.fig]() : cardFigSlot(L, i)}${k.f ? `<div class="formula">${k.f.split('\n').map(l => `<span>${vx(l)}</span>`).join('')}</div>` : ''}<p>${nlv(k.t)}</p><small class="kn">${i + 1} / ${L.cards.length}</small></article>`).join('')}</div>` +
    `<div class="dots" id="dots">${L.cards.map((_, i) => `<i class="${i ? '' : 'on'}"></i>`).join('')}</div><div class="cnav"><button class="btn line" data-act="cPrev">${ic('chevron-left')}</button><button class="btn wide" data-act="cNext" id="cnext">Дальше ${ic('chevron-right')}</button></div>`;
}
function cardsInit(key, L) {
  const S2 = lessonSteps(L), nx = S2[S2.findIndex(s => s[0] === 'cards') + 1];
  const box = $('#cards'); if (!box) return;
  box.addEventListener('scroll', () => {
    const i = Math.round(box.scrollLeft / box.clientWidth), n = box.children.length;
    $('#dots').querySelectorAll('i').forEach((d, k) => d.classList.toggle('on', k === i));
    $('#cnext').innerHTML = i >= n - 1 && nx ? `Дальше: ${nx[1]} ${ic('chevron-right')}` : `Дальше ${ic('chevron-right')}`;
    if (i >= n - 1) stepDone(key, 'cards', 15);
  }, { passive: true });
}

/* ---------- симуляции с кнопками − / + ---------- */
let G = null;
function simStart(sim, key, L) { G = { sim, key, L, round: 1, tries: 0, v: sim.param.init, res: null }; sim.newRound(G); simDraw(); }
function simDraw() {
  const { sim } = G, p = sim.param, f = d => (d > 0 ? '+' : '−') + String(Math.abs(d)).replace('.', ',');
  $('#simbox').innerHTML = `<section class="card sim"><div class="row"><b>${esc(sim.title)}</b><small>задание ${G.round} из ${sim.rounds}</small></div><p class="task">${esc(G.task)}</p><canvas id="sc" width="720" height="400"></canvas><p class="smsg ${G.res ? (G.res.ok ? 'ok' : 'bad') : ''}" id="smsg">${G.res ? esc(G.res.msg) : 'Меняй значение кнопками и жми «Проверить».'}</p>` +
    `<div class="stp"><div class="stp-h"><span>${esc(p.label)}</span><b id="sval">${p.fmt(G.v)}</b></div><div class="stp-b"><button data-step="${-p.big}">${f(-p.big)}</button><button class="m" data-step="${-p.step}">−</button><button class="m" data-step="${p.step}">+</button><button data-step="${p.big}">${f(p.big)}</button></div></div>` +
    `<button class="btn wide mt" data-act="simGo">Проверить</button></section>`;
  sim.draw($('#sc').getContext('2d'), 720, 400, G, G.v, 0);
  if (sim === SIMS.wheel) { const t0 = performance.now(); const spin = now => { if (!G || G.sim !== SIMS.wheel || !$('#sc')) return; sim.draw($('#sc').getContext('2d'), 720, 400, G, G.v, (now - t0) / 1000); G.raf = requestAnimationFrame(spin); }; G.raf = requestAnimationFrame(spin); }
}
const snap = (v, step, min, max) => { const d = (String(step).split('.')[1] || '').length; return +Math.max(min, Math.min(max, Math.round(v / step) * step)).toFixed(d); };
function simStep(d) { if (!G) return; const p = G.sim.param; G.v = snap(G.v + d, p.step, p.min, p.max); G.res = null; $('#sval').textContent = p.fmt(G.v); $('#smsg').className = 'smsg'; $('#smsg').textContent = 'Меняй значение кнопками и жми «Проверить».'; if (G.sim !== SIMS.wheel) G.sim.draw($('#sc').getContext('2d'), 720, 400, G, G.v, 0); }
function simGo() {
  G.tries++; const res = G.sim.check(G, G.v); G.res = res; const m = $('#smsg'); m.className = 'smsg ' + (res.ok ? 'ok' : 'bad'); m.textContent = res.msg;
  if (!res.ok) { buzz(25); return; }
  buzz([15, 40, 15]);
  if (G.round >= G.sim.rounds) { const key = G.key; setTimeout(() => { stepDone(key, 'sim', 20); $('#simbox').innerHTML = `<section class="card center">${ic('trophy', 'big gold')}<b class="h">Практика пройдена!</b><p class="mute">${G.sim.rounds} задания за ${plural(G.tries, 'попытку', 'попытки', 'попыток')}.</p></section>` + nextStepBtn('sim', G.L); }, 700); return; }
  setTimeout(() => { if (!G) return; G.round++; G.res = null; G.sim.newRound(G); simDraw(); }, 1200);
}
/* ---------- «Найди пару»: понятие ↔ формула или определение ---------- */
let PG = null;
function pairStart(L, key) {
  const pairs = shuffle(L.pairs).slice(0, 5);
  PG = { L, key, pairs, left: shuffle(pairs.map((_, i) => i)), right: shuffle(pairs.map((_, i) => i)), sel: null, done: new Set(), miss: 0 };
  pairDraw();
}
function pairDraw() {
  const b = (side, i) => `<button class="pc${side === 'r' && !/[а-яё]/i.test(PG.pairs[i][1]) ? ' math' : ''}${PG.done.has(i) ? ' done' : ''}${PG.sel && PG.sel.side === side && PG.sel.i === i ? ' sel' : ''}" data-act="pp" data-side="${side}" data-i="${i}"${PG.done.has(i) ? ' disabled' : ''}>${vx(PG.pairs[i][side === 'l' ? 0 : 1])}</button>`;
  $('#simbox').innerHTML = `<section class="card sim"><div class="row"><b>Найди пару</b><small>пар ${PG.done.size} из ${PG.pairs.length} · ошибок ${PG.miss}</small></div><p class="task">Нажми понятие слева, потом подходящее справа.</p><div class="pairs"><div>${PG.left.map(i => b('l', i)).join('')}</div><div>${PG.right.map(i => b('r', i)).join('')}</div></div></section>`;
}
function pairPick(side, i) {
  if (!PG || PG.done.has(i)) return;
  if (!PG.sel || PG.sel.side === side) { PG.sel = { side, i }; pairDraw(); return; }
  const ok = PG.sel.i === i; PG.sel = null;
  if (ok) { PG.done.add(i); buzz(12); } else { PG.miss++; buzz([30, 40, 30]); }
  pairDraw();
  if (!ok) { const el = document.querySelector(`.pc[data-side="${side}"][data-i="${i}"]`); if (el) el.classList.add('shake'); }
  if (PG.done.size === PG.pairs.length) {
    const { key, L, miss } = PG, st = miss === 0 ? 3 : miss <= 2 ? 2 : 1;
    setTimeout(() => { stepDone(key, 'sim', 20); $('#simbox').innerHTML = `<section class="card center">${ic('trophy', 'big gold')}<b class="h">Все пары найдены!</b>${stars(st)}<p class="mute">Ошибок: ${miss}.</p></section>` + nextStepBtn('sim', L); }, 500);
  }
}

let stepRep = null; const stepStop = () => { clearTimeout(stepRep); clearInterval(stepRep); stepRep = null; };
document.addEventListener('pointerdown', e => { const b = e.target.closest('[data-step]'); if (!b) return; e.preventDefault(); stepStop(); const go = () => simStep(+b.dataset.step); go(); stepRep = setTimeout(() => { stepRep = setInterval(go, 70); }, 380); });
['pointerup', 'pointercancel', 'pointerleave'].forEach(t => document.addEventListener(t, stepStop));

